def reubicar_cajas(apps, schema_editor):
    """Lo que ya estaba registrado se acomoda a la regla nueva: categoría técnica -> caja técnico."""
    Venta = apps.get_model("inventario", "Venta")
    Cliente = apps.get_model("inventario", "Cliente")
    Caja = apps.get_model("inventario", "CajaMovimiento")
    cero = Decimal("0")

    # 1) Cada venta toma la caja de la categoría de su producto; sus pagos al momento van con ella
    for v in Venta.objects.select_related("producto__categoria"):
        tecnica = bool(v.producto_id and v.producto.categoria.es_tecnica)
        v.caja = "TECNICO" if tecnica else "PRODUCTOS"
        v.save(update_fields=["caja"])
        Caja.objects.filter(venta_id=v.pk, origen="VENTA").update(caja=v.caja)

    # 2) Los pagos de deudas se vuelven a repartir: primero cubren lo más antiguo y van a su caja
    for cliente in Cliente.objects.all():
        pagos = list(Caja.objects.filter(cliente_id=cliente.pk, origen="ABONO").order_by("fecha", "pk"))
        if not pagos:
            continue
        saldos = [[v.caja, v.total] for v in Venta.objects.filter(cliente_id=cliente.pk, metodo="FIADO").order_by("fecha", "pk")]
        for pago in pagos:
            por_asignar, reparto = pago.monto, {}
            for s in saldos:
                if por_asignar <= 0:
                    break
                if s[1] <= 0:
                    continue
                parte = min(s[1], por_asignar)
                s[1] -= parte
                por_asignar -= parte
                reparto[s[0]] = reparto.get(s[0], cero) + parte
            if por_asignar > 0:  # sobrante improbable: se queda en la caja donde estaba
                reparto[pago.caja] = reparto.get(pago.caja, cero) + por_asignar
            if not reparto:
                continue
            (primera, monto0), *otras = reparto.items()
            pago.caja, pago.monto = primera, monto0
            pago.save(update_fields=["caja", "monto"])
            for caja, monto in otras:
                Caja.objects.create(
                    caja=caja, metodo=pago.metodo, monto=monto, concepto=pago.concepto, origen="ABONO",
                    usuario_id=pago.usuario_id, fecha=pago.fecha, cliente_id=pago.cliente_id,
                )


